import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  'linear-algebra': [
    L('Vectors: lists of numbers with a direction',
      info('Picture first', 'A **vector** is just a list of numbers. A flat described as `[3, 80]` (3 rooms, 80 square metres) is a vector with two entries.\n\nDraw it as an arrow from the origin to the point (3, 80). Two things matter: **how long** the arrow is and **which way** it points.\n\n- **Adding** two vectors: walk along the first arrow, then along the second.\n- **Scaling** by 2: the arrow gets twice as long, same direction.'),
      type('What is `[1, 2] + [3, 4]`? Write it as a list.', ['[4, 6]', '[4,6]'], 'Vectors add entry by entry.'),
      type('What is the second entry of `3 * [2, 5]`?', ['15'], 'Scaling multiplies every entry: 3 * 5 = 15.'),
      info('The dot product', 'The **dot product** multiplies matching entries and adds them up:\n\n`[2, 3] . [4, 1] = 2*4 + 3*1 = 11`\n\nIt answers: *how much do these two arrows point the same way?* Large and positive means similar direction. Zero means they meet at a right angle. Negative means they point apart.'),
      type('What is the dot product of `[2, 3]` and `[4, 1]`?', ['11'], '2 * 4 + 3 * 1 = 11.'),
      type('What is the dot product of `[1, 0]` and `[0, 7]`?', ['0'], 'The arrows lie along different axes, so they are perpendicular.'),
      mc('A dot product of exactly 0 tells you the two vectors are...', ['perpendicular', 'identical', 'opposite', 'both zero'], 'Zero dot product means a right angle (or one vector is zero).'),
      type('A neuron has weights `[0.5, 2]` and inputs `[4, 3]`. What is its weighted sum, before the bias?', ['8', '8.0'], 'A neuron is a dot product: 0.5 * 4 + 2 * 3 = 2 + 6 = 8.'),
      tf('The dot product of two vectors is another vector.', false, 'It is a single number (a scalar).')),

    L('Matrices: machines that turn vectors into vectors',
      info('A matrix is a machine', 'A **matrix** is a grid of numbers, but think of it as a machine: put a vector in, get a vector out.\n\n`[[2, 0], [0, 3]]` stretches the x-direction by 2 and the y-direction by 3. A square stays a rectangle, only bigger.\n\nOther matrices rotate, mirror or squash everything onto a line. Stack several machines and you get a neural network.'),
      type('Apply `[[2, 0], [0, 3]]` to the vector `[1, 1]`. Write the result as a list.', ['[2, 3]', '[2,3]'], 'The first entry is stretched by 2 and the second by 3.'),
      mc('What does the identity matrix `[[1, 0], [0, 1]]` do to a vector?', ['Nothing: it returns the same vector', 'It rotates it by 90 degrees', 'It doubles it', 'It sets it to zero'], 'The identity is the machine that leaves everything unchanged.'),
      info('Row times column', 'To multiply, each output entry is a **row of the first matrix dotted with a column of the second**.\n\nShapes: `(n x k) @ (k x m)` gives `n x m`. The two inner numbers must match, then they vanish.\n\nExample: `[[1, 2], [3, 4]] @ [1, 1]` gives `[1+2, 3+4] = [3, 7]`.'),
      type('What is `[[1, 2], [3, 4]] @ [1, 1]`? Write it as a list.', ['[3, 7]', '[3,7]'], 'Row [1, 2] dotted with [1, 1] is 3, and row [3, 4] gives 7.'),
      type('A has shape 5 x 3 and B has shape 3 x 2. How many columns does A @ B have?', ['2'], 'The result takes the rows of A (5) and the columns of B (2).'),
      mc('Which product is defined?', ['(2 x 3) @ (3 x 4)', '(2 x 3) @ (2 x 3)', '(4 x 2) @ (3 x 4)', '(3 x 3) @ (2 x 3)'], 'The inner sizes must match: 3 and 3.'),
      tf('For matrices, A @ B always equals B @ A.', false, 'Order matters: applying two machines in a different order gives a different result.'),
      order('Compute one entry C[0][1] of C = A @ B', ['Take row 0 of A', 'Take column 1 of B', 'Multiply matching entries', 'Add the products to get C[0][1]'], 'Each entry is a dot product of one row and one column.')),

    L('Norms, cosine similarity and the transpose',
      info('Length and angle', 'The **L2 norm** is ordinary length: `||[3, 4]|| = sqrt(9 + 16) = 5`. The **L1 norm** adds absolute values: `|3| + |4| = 7`.\n\n**Cosine similarity** removes the lengths and keeps only the angle:\n\n`cos = (a . b) / (||a|| * ||b||)`\n\nIt runs from -1 (opposite) through 0 (perpendicular) to 1 (same direction).'),
      type('What is the L2 norm of `[6, 8]`?', ['10'], 'sqrt(36 + 64) = sqrt(100) = 10.'),
      type('What is the L1 norm of `[-3, 4]`?', ['7'], 'Add the absolute values: 3 + 4 = 7.'),
      type('What is the cosine similarity of `[1, 0]` and `[0, 1]`?', ['0', '0.0'], 'Perpendicular vectors have a zero dot product.'),
      mc('Two embeddings, `[3, 4]` and `[6, 8]`, differ only in length. Their cosine similarity is...', ['1', '0.5', '0', '10'], 'Same direction means cosine 1, however long they are.'),
      info('Transpose and shapes', 'The **transpose** `A^T` swaps rows and columns: a 3 x 2 matrix becomes 2 x 3.\n\nRule: `(AB)^T = B^T A^T`.\n\nFor a data matrix `X` with one row per example and one column per feature, `X^T X` is a features-by-features matrix. It appears in regression and covariance.'),
      type('X has 100 rows (examples) and 5 columns (features). How many rows does X^T X have?', ['5'], 'X^T is 5 x 100, so X^T X is (5 x 100) @ (100 x 5) = 5 x 5.'),
      tf('The transpose of a 3 x 2 matrix has shape 2 x 3.', true, 'Rows and columns swap.'),
      match('Match the idea to its meaning', [['L1 norm', 'Sum of absolute values'], ['L2 norm', 'Ordinary length'], ['Cosine similarity', 'Angle between two vectors'], ['Dot product', 'Multiply matching entries and add']])),

    L('Inverse, rank and solving linear systems',
      info('Undoing a matrix', 'A system like `2x + y = 5` and `x + 3y = 5` is one equation `A x = b` with `A = [[2, 1], [1, 3]]`.\n\nThe **inverse** `A^-1` undoes the machine, so `x = A^-1 b`. It exists only when the machine does not squash space flat.\n\nFor a 2 x 2 matrix `[[a, b], [c, d]]` the **determinant** is `ad - bc`. Zero determinant means squashed, so no inverse.'),
      type('What is the determinant of `[[3, 1], [2, 4]]`?', ['10'], '3 * 4 - 1 * 2 = 10.'),
      type('What is the determinant of `[[1, 2], [2, 4]]`?', ['0'], '1 * 4 - 2 * 2 = 0, so the matrix has no inverse.'),
      mc('A matrix has determinant 0. What does that mean?', ['It squashes space onto a line or point, so it cannot be inverted', 'It is the identity', 'It has only zero entries', 'It is always symmetric'], 'Information is lost, so no machine can undo it.'),
      type('Solve `[[2, 0], [0, 5]] x = [6, 10]`. What is x1 + x2?', ['5'], 'x1 = 6 / 2 = 3 and x2 = 10 / 5 = 2, so the sum is 5.'),
      type('What is the bottom-right entry of the inverse of `[[2, 0], [0, 4]]`?', ['0.25', '1/4'], 'The inverse of a diagonal matrix has reciprocal entries: 1/2 and 1/4.'),
      info('Rank and regression', '**Rank** is the number of independent columns. If a third feature is just feature 1 plus feature 2, it adds no new information, so the rank is 2, not 3.\n\nLinear regression solves `w = (X^T X)^-1 X^T y`. With dependent columns `X^T X` cannot be inverted, and with nearly dependent columns the weights swing wildly. In code call `np.linalg.solve` or `lstsq`, not `inv`.'),
      type('What is the rank of `[[1, 2], [2, 4]]`?', ['1'], 'The second row is twice the first, so there is one independent row.'),
      type('A matrix has 4 rows and 3 columns. What is the largest rank it can have?', ['3'], 'Rank cannot exceed the smaller of rows and columns.'),
      tf('In code, `np.linalg.inv(A) @ b` is the preferred way to solve `A x = b`.', false, '`solve` uses a factorisation that is faster and more accurate than forming the inverse.')),

    L('Eigenvectors, SVD and PCA',
      info('Directions that do not turn', 'Most vectors change direction when a matrix acts on them. An **eigenvector** does not: it is only stretched by a number, the **eigenvalue**.\n\n`A v = lambda v`\n\nFor `[[3, 0], [0, 2]]` the x-axis is an eigenvector with eigenvalue 3 and the y-axis one with eigenvalue 2.\n\nUseful facts for a 2 x 2 matrix: eigenvalues **add up to the trace** (sum of the diagonal) and **multiply to the determinant**.'),
      type('What is the larger eigenvalue of `[[2, 1], [1, 2]]`?', ['3'], 'Trace 4 and determinant 3 give eigenvalues 3 and 1.'),
      type('For `A = [[4, 0], [0, 1]]`, what is the eigenvalue belonging to the eigenvector `[1, 0]`?', ['4'], 'A [1, 0] = [4, 0] = 4 * [1, 0].'),
      type('What is the sum of the eigenvalues of `[[5, 1], [2, 3]]`?', ['8'], 'The sum equals the trace: 5 + 3 = 8.'),
      type('What is the product of the eigenvalues of `[[5, 1], [2, 3]]`?', ['13'], 'The product equals the determinant: 5 * 3 - 1 * 2 = 13.'),
      info('SVD and PCA', 'The **SVD** writes any matrix as `U Sigma V^T`: rotate, stretch along axes by the **singular values**, rotate again. Keeping only the largest singular values gives the best low-rank copy, which is how images, embeddings and recommender tables are compressed.\n\n**PCA** finds the directions along which centred data varies most. Those are the top eigenvectors of the covariance matrix, and the eigenvalues are the variances along them.'),
      order('Run PCA', ['Subtract the mean of each feature', 'Compute the covariance matrix (or take the SVD)', 'Find its top eigenvectors', 'Project the data onto them'], 'Centre first, find the directions, then project.'),
      type('PCA components carry variances 6, 3 and 1. What fraction of the total variance does the first one explain? Answer as a decimal.', ['0.6', '60%', '60', '0.60'], '6 / (6 + 3 + 1) = 0.6.'),
      tf('PCA directions are meaningful even if you forget to subtract the mean of each feature.', false, 'Without centring, the first direction mostly points at the mean instead of the spread.'),
      match('Match the tool to its use in ML', [['Eigenvectors of the covariance', 'PCA directions'], ['Truncated SVD', 'Low-rank compression'], ['Query dot key', 'Attention score'], ['X^T X', 'Normal equation for regression']])),

    L('Common mistakes with vectors and matrices',
      info('Shape and scale bugs', 'Most linear-algebra bugs in ML code are not deep. They are:\n\n- **Shape mix-ups.** Always write the shapes next to each line: `(n, d) @ (d, k) -> (n, k)`.\n- **Star is not matrix multiplication.** In numpy `A * B` multiplies entry by entry; use `A @ B`.\n- **Broadcasting surprises.** A shape `(5,)` plus a shape `(5, 1)` gives a 5 x 5 table, not 5 numbers.\n- **Unnormalised vectors.** A dot product ranks longer vectors higher.'),
      tf('In numpy, `A * B` on two matrices is the matrix product.', false, '`*` works entry by entry; the matrix product is `A @ B`.'),
      mc('Two matrices A and B both have shape 3 x 4. What happens with `A @ B`?', ['Error: inner sizes 4 and 3 do not match', 'A 3 x 4 result', 'A 4 x 4 result', 'A 3 x 3 result'], 'Multiplication needs the columns of A to equal the rows of B.'),
      type('In numpy, `np.ones(5) + np.ones((5, 1))` produces an array with how many entries?', ['25'], 'Broadcasting expands shapes (5,) and (5, 1) into a 5 x 5 table.'),
      fillc('C = A ___ B   # matrix product in numpy', ['@', '*', '+', '//'], '`@` is the matrix multiplication operator.'),
      info('Scale and centring', 'Features on different scales distort geometry. If one column is a salary in the tens of thousands and another is age, salary dominates every distance and every principal component. **Standardise** features (subtract the mean, divide by the standard deviation) before PCA, nearest neighbours or regularised regression.\n\nAlso remember: cosine similarity compares direction only, so it is the right tool when length is not meaningful.'),
      mc('You run PCA on salary (around 50,000) and age (around 40) without scaling. What happens?', ['The first component is almost entirely salary', 'Age dominates the first component', 'PCA fails with an error', 'Both get equal weight'], 'PCA chases variance, and salary has far larger raw variance.'),
      mc('You rank documents by raw dot product of unnormalised embeddings. What bias appears?', ['Longer vectors tend to rank higher regardless of direction', 'Shorter vectors rank higher', 'No bias, it equals cosine', 'Ranking becomes random'], 'The dot product grows with length; normalise first to compare direction.'),
      tf('Cosine similarity needs the two vectors to have the same number of entries.', true, 'The dot product needs matching entries, so the dimensions must agree.')),

    L('Case study: semantic search for a help centre',
      info('The scenario', 'A company wants search over **50,000 help articles**. Each article is turned into a **384-number embedding** by a model, stored as float32 (4 bytes per number). A user query is embedded the same way, and the closest articles are shown.\n\nYou are the engineer. Every decision below is a piece of linear algebra.'),
      type('How many megabytes do the article vectors take? (50,000 x 384 numbers x 4 bytes; 1 MB = 1,000,000 bytes.) Give a decimal.', ['76.8'], '50,000 * 384 = 19.2 million numbers, times 4 bytes is 76.8 MB.'),
      type('Exact search compares the query with every article. How many multiplications is that per query?', ['19200000', '19,200,000'], 'One dot product of 384 multiplications per article: 50,000 * 384 = 19.2 million.'),
      mc('Early tests show long articles ranking above better short ones with raw dot products. What is the best fix?', ['Normalise every vector to length 1, then use the dot product (cosine)', 'Multiply scores by article length', 'Use only the first 10 numbers', 'Sort alphabetically'], 'Normalising removes the length effect, so only direction counts.'),
      info('Scaling up', 'Next year the library grows to **50 million** articles. Exact search would need about 19 billion multiplications per query, too slow for a 5 ms budget.\n\nTwo levers: an **approximate nearest-neighbour index** (graph or cluster based) that checks only a small fraction of vectors, and **compression**, for instance PCA down to 128 dimensions.'),
      type('After PCA to 128 dimensions, how many megabytes do the original 50,000 vectors need? Give a decimal.', ['25.6'], '50,000 * 128 * 4 bytes = 25.6 MB.'),
      mc('PCA to 128 dimensions drops top-10 recall from 98% to 90% against exact search. What do you do?', ['Try 192 or 256 dimensions and measure recall against the memory saved', 'Ship it, 90% is fine', 'Remove the index', 'Use fewer articles'], 'Pick the dimension from a measured recall versus cost trade-off.'),
      tf('Ranking by cosine similarity gives the same order as ranking by raw dot product, even for unnormalised vectors.', false, 'They agree only when all vectors have the same length, for instance after normalising.'),
      order('Order the search pipeline', ['Embed every article with one model', 'Normalise each vector to length 1', 'Build an index over the vectors', 'Embed and normalise the query with the same model', 'Return the top k articles by dot product'], 'Index and query must use the same model and normalisation.')),

    L('Interview drill: linear algebra',
      info('How to answer', 'Interviewers want a short, structured answer:\n\n1. **Define** the idea in one sentence.\n2. Give a **tiny numeric example**.\n3. Say **where it appears in ML**.\n4. Name a **pitfall or trade-off**.\n\nPractise saying shapes aloud: it shows you can reason about real code.'),
      type('Quick: what is the dot product of `[1, 2, 3]` and `[0, 1, 2]`?', ['8'], '0 + 2 + 6 = 8.'),
      type('A dense layer maps 10 inputs to 4 outputs with a bias. How many parameters does it have?', ['44'], '10 * 4 weights plus 4 biases is 44.'),
      type('How many multiplications does `(100 x 50) @ (50 x 20)` need?', ['100000', '100,000'], '100 * 50 * 20 = 100,000: each of the 100 x 20 outputs needs 50 multiplications.'),
      mc('Which is the best one-sentence answer to "What is an eigenvector?"', ['A direction the matrix only stretches or flips, by a factor called the eigenvalue', 'A vector with length one', 'The largest row of a matrix', 'A vector whose entries are all equal'], 'Eigenvectors keep their direction under the transformation.'),
      mc('Why is SVD used in recommender systems?', ['It factors the user-item table into a few latent factors, a low-rank approximation', 'It sorts items by price', 'It inverts the matrix exactly', 'It removes all missing values'], 'A few singular directions capture most of the taste patterns.'),
      tf('A rank-1 matrix has every row equal to a multiple of one row.', true, 'Rank 1 means one independent direction.'),
      order('Structure of a strong spoken answer', ['Define the idea in one sentence', 'Give a tiny numeric example', 'Say where it appears in ML', 'Mention a pitfall or trade-off'], 'This keeps answers short and complete.'),
      match('Match the interview question to its key point', [['Why not use inv(A)?', 'Solving by factorisation is faster and more accurate'], ['Why normalise embeddings?', 'Cosine becomes a dot product'], ['Why standardise before PCA?', 'Large-scale features dominate variance'], ['Why does collinearity hurt regression?', 'X^T X is nearly singular']]))
  ]
,
  calculus: [
    L('Slopes: what a derivative tells you',
      info('A slope at a point', 'Walk along a hilly path. At each spot the ground is steeper or flatter, uphill or downhill. The **derivative** is that slope, written as a number for each position.\n\nFor `f(x) = x^2`, the slope at x = 3 is 6; at x = 0 it is 0 (the bottom of the bowl); at x = -3 it is -6 (going downhill).\n\nThree rules cover most cases:\n\n- `x^n` has derivative `n * x^(n-1)`\n- a constant has derivative 0\n- slopes of added terms add'),
      type('What is the derivative of `x^2` at x = 5?', ['10'], 'The derivative is 2x, which is 10 at x = 5.'),
      type('What is the derivative of `3x + 7`?', ['3'], 'The constant 7 disappears and 3x has a constant slope of 3.'),
      type('What is the derivative of `x^4` at x = 1?', ['4'], '4 * x^3 = 4 at x = 1.'),
      mc('The slope of a loss at the current weight is positive. To lower the loss you should move the weight...', ['Down (to the left)', 'Up (to the right)', 'Nowhere', 'To zero'], 'A positive slope means the loss rises to the right, so go left.'),
      info('Flat means turning point', 'At the very bottom of a smooth bowl the slope is **zero**. So to find a minimum, find where the derivative is zero.\n\n`f(x) = (x - 3)^2` has slope `2(x - 3)`, which is zero at x = 3. The loss there is 0, its lowest value.'),
      type('For `f(x) = (x - 3)^2`, at which x is the slope zero?', ['3'], '2(x - 3) = 0 gives x = 3.'),
      type('For `f(x) = x^2 - 4x`, at which x is the slope zero?', ['2'], 'The derivative is 2x - 4, which is 0 at x = 2.'),
      tf('At the minimum of a smooth function, the slope is zero.', true, 'The curve has flattened out before turning upwards.'),
      fill('Where the slope is positive and you want a smaller value, move ___.', ['left', 'right', 'up', 'nowhere'], 'The function is rising to the right, so the smaller values are on the left.')),

    L('Gradients and your first descent steps',
      info('Many inputs, many slopes', 'A model has many weights, so the loss depends on many inputs. A **partial derivative** is the slope along one input while holding the others fixed.\n\nFor `f(x, y) = x^2 + y^2` (a round bowl): `df/dx = 2x` and `df/dy = 2y`.\n\nThe **gradient** stacks them: `[2x, 2y]`. It is an arrow pointing straight uphill, and it gets longer the steeper the ground is.'),
      type('For `f(x, y) = x^2 + y^2`, what is df/dx at the point (3, 4)?', ['6'], '2x = 6.'),
      type('For the same function, what is the second entry of the gradient at (3, 4)?', ['8'], '2y = 8.'),
      type('What is the first entry of the gradient of `f(x, y) = 3x + 2y`?', ['3'], 'The slope in the x direction is the constant 3.'),
      info('Walking downhill', '**Gradient descent** takes a small step against the gradient:\n\n`w = w - lr * slope`\n\nExample: `f(w) = w^2`, start at `w = 4`, learning rate `lr = 0.1`. The slope is `2w = 8`, so the new `w = 4 - 0.1 * 8 = 3.2`.'),
      type('Continuing: after the first step w = 3.2. What is w after the second step? Give a decimal.', ['2.56'], 'The slope is 6.4, so w = 3.2 - 0.1 * 6.4 = 2.56.'),
      mc('Gradient descent moves the weights in which direction?', ['Opposite to the gradient', 'Along the gradient', 'Perpendicular to the gradient', 'Towards zero always'], 'The gradient points uphill, so we go the other way.'),
      tf('A larger learning rate always makes training converge faster.', false, 'Too large and the steps overshoot the minimum and the loss can grow.'),
      order('The gradient descent loop', ['Pick starting parameters', 'Compute the gradient of the loss', 'Subtract learning rate times gradient', 'Repeat until the loss stops improving'], 'Compute, step, repeat.')),

    L('The chain rule and computation graphs',
      info('Derivatives of nested functions', 'Models are functions inside functions. The **chain rule** multiplies the slopes of each layer:\n\n`y = (3x + 1)^2`. Let `u = 3x + 1`, so `y = u^2`. Then `dy/dx = (dy/du) * (du/dx) = 2u * 3`.\n\nThink of gears: if the first gear turns the second twice as fast and the second turns the third three times as fast, the third turns six times as fast.'),
      type('What is the derivative of `(2x + 1)^2` at x = 1?', ['12'], 'Chain rule: 2(2x + 1) * 2 = 2 * 3 * 2 = 12.'),
      type('What is the derivative of `(x^2 + 1)^3` at x = 1?', ['24'], '3(x^2 + 1)^2 * 2x = 3 * 4 * 2 = 24.'),
      type('A sigmoid unit outputs 0.8. Its derivative is output * (1 - output). What is it?', ['0.16'], '0.8 * 0.2 = 0.16.'),
      info('Backprop on a tiny graph', 'Take one weight: `p = w * x`, `L = (p - y)^2` with `w = 2`, `x = 3`, `y = 5`.\n\nForward: `p = 6`, `L = (6 - 5)^2 = 1`.\n\nBackward, multiply local slopes from the loss to the weight:\n\n`dL/dp = 2(p - y) = 2`\n`dp/dw = x = 3`\n`dL/dw = 2 * 3 = 6`'),
      type('In this example, what is dL/dw?', ['6'], 'dL/dp * dp/dw = 2 * 3 = 6.'),
      type('Same graph but y = 8 (w = 2, x = 3). What is dL/dp?', ['-4'], 'p = 6, so 2(p - y) = 2 * (-2) = -4.'),
      order('Backpropagation', ['Run the forward pass and store each value', 'Compute the loss', 'Start with dL/dL = 1', 'Multiply local derivatives backwards to every weight'], 'Backward flow reuses the stored forward values.'),
      mc('Why does backprop store the values from the forward pass?', ['Local derivatives depend on them', 'To save memory', 'To shuffle the data', 'To make the loss smaller'], 'For example dp/dw needs the input x.')),

    L('Gradients of common losses and the descent family',
      info('Losses and their gradients', 'You will meet three gradients again and again:\n\n- **Mean squared error:** for one prediction `p` and target `y`, `d/dp (p - y)^2 = 2(p - y)`. Over n examples the loss is averaged, so each gradient is divided by n.\n- **Sigmoid with binary cross-entropy:** the gradient with respect to the logit is `p - y`.\n- **Softmax with cross-entropy:** also `p - y`, a vector of probabilities minus a one-hot label.'),
      type('Predictions [2, 4] and targets [3, 2]. What is the mean squared error?', ['2.5'], '((2-3)^2 + (4-2)^2) / 2 = (1 + 4) / 2 = 2.5.'),
      type('A sigmoid classifier outputs p = 0.9 and the label is 1. What is the gradient of the loss with respect to the logit?', ['-0.1'], 'p - y = 0.9 - 1 = -0.1.'),
      type('The classifier outputs p = 0.2 and the label is 0. What is the gradient with respect to the logit?', ['0.2'], 'p - y = 0.2 - 0 = 0.2.'),
      info('Batches, momentum and Adam', 'Using all data for each step is **batch** descent. One example is **SGD**. A group of 32 to 1024 is a **mini-batch**, the usual choice.\n\n**Momentum** keeps a running velocity: `v = 0.9 * v - lr * g`, then `w = w + v`. It damps zigzags.\n\n**Adam** also scales each parameter step by a running average of its squared gradients, so each weight gets its own step size.'),
      type('You have 1,000 examples and a batch size of 100. How many steps make one epoch?', ['10'], '1,000 / 100 = 10.'),
      type('50,000 examples, batch size 250, trained for 3 epochs. How many update steps in total?', ['600'], '50,000 / 250 = 200 steps per epoch, times 3 is 600.'),
      type('Momentum with v = 1, lr = 0.1 and gradient g = 2 uses `v = 0.9 * v - lr * g`. What is the new v?', ['0.7'], '0.9 * 1 - 0.1 * 2 = 0.7.'),
      mc('What is the main benefit of Adam over plain SGD?', ['Per-parameter adaptive step sizes', 'It needs no learning rate', 'It always finds the global minimum', 'It makes gradients exact'], 'Parameters with small or rare gradients still take useful steps.'),
      tf('On average, a mini-batch gradient equals the full-batch gradient.', true, 'It is a noisy but unbiased estimate when batches are sampled randomly.')),

    L('Convexity, learning rates, saddle points, Jacobians and Hessians',
      info('Curvature controls the step size', 'The second derivative measures **curvature**. For `f(w) = w^2` it is 2. On such a bowl one step of gradient descent turns `w` into `w - lr * 2w = (1 - 2 lr) w`.\n\n- `lr = 0.25` gives a factor 0.5, so w halves each step.\n- `lr = 1.0` gives a factor -1, so w flips sign forever.\n- `lr = 1.5` gives a factor -2, so w doubles in size each step and **diverges**.\n\nSo the safe learning rate shrinks as curvature grows.'),
      type('f(w) = w^2, lr = 0.25, start w = 4. What is w after two steps?', ['1'], 'Each step halves w: 4, 2, 1.'),
      type('f(w) = w^2, lr = 1.0, start w = 1. What is w after one step?', ['-1'], 'w - 1.0 * 2w = -w.'),
      mc('f(w) = w^2 with lr = 1.5. What happens?', ['w alternates in sign and grows each step: it diverges', 'It converges to 0', 'It stays at the start', 'It converges to 1.5'], 'The factor 1 - 2 * 1.5 = -2 doubles the size each step.'),
      info('Saddles, Jacobian and Hessian', 'A **convex** loss is a single bowl: any minimum is the global one. Deep networks are not convex.\n\nAt `f(x, y) = x^2 - y^2` the origin has zero gradient, yet it curves up along x and **down** along y. That is a **saddle point**. Zero gradient does not mean a minimum.\n\nA **Jacobian** collects all first derivatives of a function with several outputs (rows are outputs, columns are inputs). The **Hessian** collects all second derivatives of a scalar function: an n x n table for n parameters.'),
      type('A function takes 3 inputs and returns 2 outputs. How many entries does its Jacobian have?', ['6'], 'It has 2 rows and 3 columns.'),
      type('A model has 1,000 parameters. How many entries does its Hessian have?', ['1000000', '1,000,000'], '1,000 x 1,000 = 1,000,000, which is why large networks avoid it.'),
      tf('If the gradient is zero, the point must be a minimum.', false, 'It could also be a maximum or a saddle point.'),
      mc('At the origin of f(x, y) = x^2 - y^2, the gradient is zero and the curvature is +2 along x and -2 along y. What is the point?', ['A saddle point', 'A minimum', 'A maximum', 'Not stationary'], 'Curving up in one direction and down in another defines a saddle.')),

    L('Common mistakes when optimising',
      info('Silent training bugs', 'Optimisation bugs rarely crash. They just make the loss refuse to fall:\n\n- **Learning rate too high:** loss jumps or becomes NaN.\n- **Wrong sign:** adding the gradient maximises the loss.\n- **Sum instead of mean:** a loss summed over 64 examples has a 64 times bigger gradient, like a 64 times bigger learning rate.\n- **Forgetting to reset gradients** (for example `zero_grad()` in PyTorch): they pile up from step to step.\n- **Unscaled inputs:** one huge feature makes the surface a narrow valley.'),
      mc('The loss becomes NaN within the first few steps. What is the most likely cause?', ['The learning rate is far too high', 'The dataset is too small', 'The batch is too large', 'There are too few epochs'], 'Huge steps overflow the numbers.'),
      tf('Updating with `w = w + lr * grad` minimises the loss.', false, 'That climbs uphill; the minus sign is what descends.'),
      type('You sum the loss over a batch of 64 examples instead of averaging it. By what factor is the gradient larger?', ['64'], 'The sum is 64 times the mean, and so is its gradient.'),
      fillc('w = w - lr * ___   # one gradient descent update', ['grad', 'loss', 'lr', 'w'], 'The step uses the gradient of the loss with respect to w.'),
      mc('In PyTorch you forget `optimizer.zero_grad()` in the training loop. What happens?', ['Gradients accumulate across steps and updates become wrong', 'Training is faster', 'Nothing, it resets automatically', 'The model stops using the GPU'], 'Each backward pass adds to the stored gradients unless they are cleared.'),
      info('Saturation and numerical traps', 'The sigmoid slope is at most 0.25. In a deep stack of sigmoid layers, backprop multiplies many numbers below 0.25, so early layers receive almost no gradient (**vanishing gradients**). ReLU, good initialisation, normalisation and residual connections avoid this.\n\nAlso beware `log(0)`: clip probabilities to a tiny positive value before taking logs in a cross-entropy.'),
      type('In the best case, each sigmoid layer multiplies the gradient by 0.25. By what number is the gradient multiplied after 3 layers? Give a decimal.', ['0.015625', '1/64'], '0.25^3 = 0.015625.'),
      mc('A cross-entropy loss produces `inf` because a predicted probability is exactly 0. What is the standard fix?', ['Clip probabilities away from 0, or compute from logits with a stable function', 'Remove that example', 'Increase the learning rate', 'Use a smaller batch'], 'log(0) is minus infinity, so keep probabilities inside a small positive range.')),

    L('Case study: training a click-through model',
      info('The scenario', 'An advertising team trains a **logistic regression** to predict whether a user clicks. There are **1,000,000 training examples**, a mini-batch of **500**, and about 2% of examples are clicks. You decide the training settings and read the curves.'),
      type('How many update steps make one epoch?', ['2000', '2,000'], '1,000,000 / 500 = 2,000.'),
      type('For one example with predicted click probability 0.05 and a true click (label 1), what is the gradient of the loss with respect to the logit?', ['-0.95'], 'p - y = 0.05 - 1 = -0.95: a strong push upwards.'),
      mc('With learning rate 0.5 the loss becomes NaN after three steps. What do you try first?', ['Cut the learning rate by 10 times and check feature scaling', 'Double the batch size and keep the rate', 'Remove the bias term', 'Train for more epochs'], 'Divergence points to steps that are too big, often because some features are unscaled.'),
      info('Reading the curves', 'After a rerun with lr 0.05 the **training loss keeps falling**, but the **validation loss** starts to rise at epoch 5. The model has begun memorising the training set.\n\nUseful tools: **early stopping** (keep the epoch with the best validation loss), a **learning-rate schedule** (large steps early, small steps later) and regularisation.'),
      mc('Training loss falls steadily while validation loss rises after epoch 5. What is the best decision?', ['Stop at the epoch with the best validation loss, and consider regularisation', 'Train much longer', 'Increase the learning rate', 'Delete the validation set'], 'Rising validation loss with falling training loss is overfitting.'),
      type('A schedule starts at lr 0.08 and halves every 2 epochs (epochs 0 and 1 use 0.08). What is the learning rate in epoch 6? Give a decimal.', ['0.01'], 'Epoch 2 gives 0.04, epoch 4 gives 0.02 and epoch 6 gives 0.01.'),
      tf('You should run a numerical gradient check on the full production-size model.', false, 'Gradient checks are slow, so run them on a tiny model or a few parameters.'),
      order('Debugging a loss that will not decrease', ['Try to overfit a tiny batch of 10 examples', 'Run a numerical gradient check on a small model', 'Lower the learning rate by 10 times', 'Check that inputs are scaled', 'Only then change the architecture'], 'Cheap, targeted checks come before big redesigns.')),

    L('Interview drill: calculus and optimisation',
      info('What interviewers probe', 'Expect three styles:\n\n1. **Quick derivatives**: power rule, chain rule, a partial derivative.\n2. **Hand-run optimisation**: one or two gradient steps with given numbers.\n3. **Concept questions**: why Adam, why cross-entropy, what saddle points are, why the learning rate matters.\n\nAlways say the sign convention aloud: "I subtract the gradient, because it points uphill."'),
      type('What is the derivative of `5x^3` at x = 1?', ['15'], '15x^2 = 15 at x = 1.'),
      type('For `f(x, y) = x^2 * y + y^3`, what is df/dy at (1, 2)?', ['13'], 'x^2 + 3y^2 = 1 + 12 = 13.'),
      type('f(w) = w^2, start w = 5, lr = 0.5. What is w after one gradient step?', ['0'], 'The slope is 10, so w = 5 - 0.5 * 10 = 0.'),
      mc('Is the training loss of a deep neural network convex?', ['No: it is non-convex, with many minima and saddle points', 'Yes, always', 'Only with ReLU', 'Only with Adam'], 'Composing layers with nonlinearities breaks convexity.'),
      mc('What is the gradient of softmax cross-entropy with respect to the logits?', ['Predicted probabilities minus the one-hot label', 'The label minus the logits', 'The logits squared', 'Zero at initialisation'], 'It is p - y, large when the model is confidently wrong.'),
      tf('Doubling the learning rate always halves the training time.', false, 'Past a limit the steps overshoot and training slows or diverges.'),
      order('Structure of a strong answer to "Explain gradient descent"', ['Say what the gradient is', 'Give the update rule', 'Explain the role of the learning rate', 'Mention variants such as mini-batch and Adam'], 'Intuition, formula, key parameter, then practical variants.'),
      match('Match the term to its role', [['Chain rule', 'Gives gradients through layers (backprop)'], ['Momentum', 'Damps zigzag and builds speed'], ['Hessian', 'Describes curvature'], ['Learning-rate warm-up', 'Stabilises the first steps']]))
  ]
,
  probability: [
    L('Chance, expectation and spread',
      info('Probability in one picture', 'A **probability** is a number from 0 (never) to 1 (certain). A fair coin lands heads with probability 0.5: out of 1,000 flips, expect about 500 heads.\n\n- The chance something does **not** happen is `1 - p`.\n- For **independent** events (one does not affect the other) the chance both happen is the **product**: two heads in a row is `0.5 * 0.5 = 0.25`.'),
      type('You roll a fair six-sided die. What is the probability of an even number? Give a decimal.', ['0.5', '1/2', '50%'], 'Three of the six faces (2, 4, 6) are even.'),
      type('You flip two fair coins. What is the probability of two heads? Give a decimal.', ['0.25', '1/4', '25%'], 'Independent events multiply: 0.5 * 0.5.'),
      type('You flip two fair coins. What is the probability of at least one head? Give a decimal.', ['0.75', '3/4', '75%'], 'The only way to fail is two tails (0.25), so the answer is 1 - 0.25.'),
      info('Expectation', 'A **random variable** is a number decided by chance, such as a die roll. Its **expectation** is the long-run average: weight each value by its probability and add.\n\nA game pays 10 points with probability 0.1 and nothing otherwise: `E = 10 * 0.1 + 0 * 0.9 = 1` point per play. The expectation does not have to be a value you can actually get: a die averages 3.5.'),
      type('A spinner lands on 2, 4 or 6 with equal chance. What is the expected value?', ['4', '4.0'], '(2 + 4 + 6) / 3 = 4.'),
      type('A bet loses 1 point with probability 0.6 and wins 2 points with probability 0.4. What is the expected result per bet? Give a decimal.', ['0.2'], '-1 * 0.6 + 2 * 0.4 = -0.6 + 0.8 = 0.2.'),
      mc('What does the **variance** of a random variable describe?', ['How spread out the values are around the mean', 'The most likely value', 'The biggest possible value', 'The number of outcomes'], 'It is the average squared distance from the mean.'),
      tf('The expected value of a random variable must be a value it can actually take.', false, 'A fair die has expectation 3.5, which is not a face.')),

    L('Conditional probability and Bayes by counting',
      info('Counting people instead of using formulas', 'Imagine **1,000 emails**. 200 are spam and 800 are not. The word "free" appears in 120 of the spam emails and in 40 of the non-spam ones.\n\n- Of the 200 spam, 120 contain "free", so **P(free | spam) = 120 / 200 = 0.6**. Read "|" as "given that".\n- Of all 160 emails containing "free", 120 are spam, so **P(spam | free) = 120 / 160 = 0.75**.\n\nThe two are different questions. Counting makes that obvious.'),
      type('Using the 1,000 emails above, what is P(free | spam)? Give a decimal.', ['0.6', '60%', '3/5'], '120 of the 200 spam emails contain the word.'),
      type('What is P(spam | free)? Give a decimal.', ['0.75', '75%', '3/4'], 'Of the 160 emails with the word (120 + 40), 120 are spam.'),
      mc('Why are P(spam | free) and P(free | spam) different?', ['They answer different questions and divide by different groups', 'They are always equal', 'One of them is always 1', 'The second is the complement of the first'], 'The first divides by emails with the word, the second by spam emails.'),
      info('Joint, marginal, independent', 'The **joint** probability `P(A and B)` is the chance of both. The **marginal** `P(A)` is the chance of A alone, found by adding the joint over all values of B.\n\n`P(A | B) = P(A and B) / P(B)`\n\nA and B are **independent** when knowing one changes nothing: `P(A | B) = P(A)`, so `P(A and B) = P(A) * P(B)`.'),
      type('P(rain and late) = 0.1 and P(rain) = 0.4. What is P(late | rain)? Give a decimal.', ['0.25', '1/4', '25%'], '0.1 / 0.4 = 0.25.'),
      type('A and B are independent with P(A) = 0.5 and P(B) = 0.2. What is P(A and B)? Give a decimal.', ['0.1', '10%'], 'Independent events multiply: 0.5 * 0.2.'),
      mc('How do you get the marginal probability of A from a joint table?', ['Add the joint probabilities over all values of B', 'Multiply by P(B)', 'Take the largest entry', 'Subtract P(B)'], 'Summing over the other variable removes it.'),
      tf('If two events are independent, learning that one happened does not change the probability of the other.', true, 'That is the definition of independence.')),

    L('Common distributions',
      info('A small zoo', 'A few distributions cover most of ML:\n\n- **Bernoulli(p):** one yes or no. Mean p, variance p(1 - p).\n- **Binomial(n, p):** number of yes answers in n tries. Mean np, variance np(1 - p).\n- **Poisson(lambda):** number of events in a fixed window at average rate lambda. Mean and variance both lambda.\n- **Uniform(a, b):** every value in the range equally likely.'),
      type('X is Binomial with n = 20 and p = 0.1. What is its mean?', ['2', '2.0'], 'n * p = 2.'),
      type('X is Binomial with n = 100 and p = 0.5. What is its variance?', ['25', '25.0'], 'n * p * (1 - p) = 100 * 0.25 = 25.'),
      type('Tickets arrive as a Poisson process at an average of 4 per hour. What is the average number in a 30-minute window?', ['2', '2.0'], 'The rate scales with time: 4 * 0.5 = 2.'),
      tf('For a Poisson distribution the mean equals the variance.', true, 'Both equal lambda; counts with larger variance are called overdispersed.'),
      info('Normal and exponential', 'The **normal** (bell curve) with mean `mu` and standard deviation `sigma` describes sums and averages of many small effects. About 68% of values fall within 1 sigma of the mean and 95% within 2 sigma. A **z-score** is `(x - mu) / sigma`.\n\nThe **exponential** with rate `lambda` describes the waiting time until the next event: mean `1 / lambda`. It is **memoryless**: having waited already tells you nothing about the rest of the wait.'),
      type('Heights have mean 100 and standard deviation 15. What is the z-score of 130?', ['2', '2.0'], '(130 - 100) / 15 = 2.'),
      type('For the same distribution, what is the lower end of the range that holds about 95% of the values?', ['70'], 'Two standard deviations below the mean: 100 - 30 = 70.'),
      type('Waiting times are exponential with rate 2 per minute. What is the mean wait in minutes? Give a decimal.', ['0.5', '1/2'], 'The mean is 1 / lambda = 0.5.'),
      match('Match the situation to a distribution', [['One click or no click', 'Bernoulli'], ['Tickets per hour', 'Poisson'], ['Time until the next ticket', 'Exponential'], ['A random starting value anywhere in a range', 'Uniform']])),

    L('Bayes’ rule and maximum likelihood',
      info('Bayes’ rule with natural frequencies', '`P(A | B) = P(B | A) * P(A) / P(B)`: posterior = likelihood x prior / evidence.\n\nA condition affects 1% of people. A test finds 90% of true cases and also gives a positive result for 9% of healthy people. Take **10,000 people**:\n\n- 100 are ill, and 90 of them test positive.\n- 9,900 are healthy, and 891 of them test positive.\n\nSo `P(ill | positive) = 90 / (90 + 891)`.'),
      type('In this example, how many of the 10,000 people test positive in total?', ['981'], '90 + 891 = 981.'),
      type('What is P(ill | positive), as a percentage rounded to the nearest whole number?', ['9', '9%', '9.2', '9.17'], '90 / 981 is about 9.2%: most positives are false alarms because the condition is rare.'),
      mc('If the condition affected 10% of people instead of 1%, with the same test, what happens to P(ill | positive)?', ['It rises a lot', 'It falls', 'It stays the same', 'It becomes 100%'], 'A higher prior means more of the positives are real cases.'),
      info('Maximum likelihood', 'The **likelihood** is the probability of the data you saw, as a function of the parameters. **Maximum likelihood estimation (MLE)** picks the parameters that make the data most likely.\n\nA coin gives 7 heads and 3 tails. The likelihood `p^7 (1 - p)^3` peaks at `p = 7/10`. In general the MLE of a probability is the observed fraction, of a Poisson rate or normal mean is the sample average, and of a normal variance is the average squared deviation (divide by n).\n\nWe maximise the **log**-likelihood: a product of many small numbers becomes a sum, which is easier and avoids underflow.'),
      type('7 heads and 3 tails. What is the maximum-likelihood estimate of p? Give a decimal.', ['0.7', '7/10', '70%'], 'The MLE is the observed fraction of heads.'),
      type('Event counts per hour are 1, 5, 3 and 3. What is the maximum-likelihood Poisson rate?', ['3', '3.0'], 'The Poisson MLE is the average count: 12 / 4 = 3.'),
      type('Data are 1, 3, 5, 7. What is the maximum-likelihood variance of a normal fitted to them (divide by n)?', ['5', '5.0'], 'The mean is 4 and the squared deviations are 9, 1, 1, 9, which sum to 20; 20 / 4 = 5.'),
      type('A coin with p = 0.5 is flipped three times. What is the probability of the sequence heads, heads, tails? Give a decimal.', ['0.125', '1/8'], '0.5 * 0.5 * 0.5 = 0.125.'),
      tf('The maximum-likelihood estimate of a variance divides by n - 1.', false, 'The MLE divides by n; dividing by n - 1 gives the unbiased estimate.')),

    L('Entropy, cross-entropy and KL divergence',
      info('Surprise', 'An event with probability `p` carries **surprise** `-log2(p)` bits: rare events surprise you more. A 1-in-8 event has `-log2(1/8) = 3` bits.\n\n**Entropy** is the average surprise of a distribution, the least number of bits per outcome any code can achieve. A fair coin has 1 bit; a coin that always lands heads has 0 bits; 4 equally likely outcomes have 2 bits.'),
      type('How many bits of surprise does an event with probability 1/8 carry?', ['3'], '-log2(1/8) = 3.'),
      type('What is the entropy, in bits, of 4 equally likely outcomes?', ['2'], 'Each outcome has surprise log2(4) = 2 bits.'),
      info('Cross-entropy and KL', 'Suppose the truth is `p = [0.5, 0.25, 0.25]` but your model says `q = [0.25, 0.25, 0.5]`.\n\n- **Entropy** `H(p) = 0.5*1 + 0.25*2 + 0.25*2 = 1.5` bits.\n- **Cross-entropy** `H(p, q)` is the average surprise under the **model**, weighted by the truth: `0.5*2 + 0.25*2 + 0.25*1 = 1.75` bits.\n- **KL divergence** is the extra cost: `KL(p || q) = H(p, q) - H(p) = 0.25` bits.\n\nKL is never negative, is zero only when p = q, and is not symmetric.'),
      type('In this example, what is the cross-entropy H(p, q) in bits? Give a decimal.', ['1.75'], 'Weight the model surprise 2, 2 and 1 bits by the true probabilities 0.5, 0.25 and 0.25.'),
      type('What is the entropy H(p) in bits? Give a decimal.', ['1.5'], '0.5 * 1 + 0.25 * 2 + 0.25 * 2 = 1.5.'),
      type('What is KL(p || q) in bits? Give a decimal.', ['0.25'], 'Cross-entropy minus entropy: 1.75 - 1.5.'),
      type('A classifier gives probability 0.5 to the true class. What is its cross-entropy loss in bits?', ['1', '1.0'], '-log2(0.5) = 1 bit (0.693 in natural log).'),
      mc('Which statement about KL divergence is correct?', ['KL(p || q) is usually different from KL(q || p)', 'It is a symmetric distance', 'It can be negative', 'It is always 1'], 'KL is not symmetric, so it is a divergence, not a distance.'),
      tf('Minimising the cross-entropy against fixed training labels is the same as maximising their likelihood.', true, 'Cross-entropy is the average negative log-likelihood of the labels.')),

    L('Common mistakes with probabilities',
      info('Four classic traps', '- **Swapping the condition:** P(positive | ill) is not P(ill | positive).\n- **Ignoring the base rate:** a 99% accurate test on a 1-in-1,000 event gives mostly false alarms.\n- **Assuming independence:** features such as words in a message are usually dependent. Naive Bayes assumes independence on purpose and is still useful, but its probabilities are overconfident.\n- **Gambler’s fallacy:** after five heads in a row a fair coin is still 50:50.'),
      mc('A test is 99% accurate and the condition affects 1 in 1,000 people. A person tests positive. What is the likely situation?', ['Most positives are still false alarms', 'The person almost certainly has it', 'The chance is exactly 99%', 'The test is useless'], 'With a tiny base rate the false positives outnumber the true ones.'),
      tf('After five heads in a row, a fair coin is more likely to land tails next.', false, 'Flips are independent, so the next flip is still 50:50.'),
      mc('You multiply 1,000 small probabilities to get a likelihood and the answer prints as 0.0. What is the standard fix?', ['Add log-probabilities instead of multiplying', 'Use integers', 'Divide by 1,000', 'Round the probabilities up'], 'The product underflows; sums of logs stay in a safe range.'),
      type('Two independent events have probabilities 0.1 and 0.01. What is the sum of their base-10 logarithms?', ['-3'], 'log10(0.1) = -1 and log10(0.01) = -2, and the sum is the log of the product.'),
      info('Counting and smoothing', 'A naive Bayes spam filter estimates `P(word | spam)` by counting. If a word never appeared in spam during training, its count is 0 and the whole product becomes 0, however strong the other evidence is.\n\n**Laplace smoothing** adds 1 to every count and adds the vocabulary size to the total, so nothing has probability exactly 0.\n\nAlso remember that **sample variance** divides by `n - 1` to avoid underestimating the spread; the MLE divides by `n` and is slightly too small on small samples.'),
      type('Spam messages contain 10 words in total, the vocabulary has 5 distinct words, and the word "prize" never appeared. What is its Laplace-smoothed probability? Give a fraction.', ['1/15', '0.0667', '0.067', '0.07'], '(0 + 1) / (10 + 5) = 1/15.'),
      mc('A language model assigns probability 0 to the correct next token in the test set. What happens to its cross-entropy on that token?', ['It becomes infinite', 'It becomes 0', 'It becomes 1', 'It is ignored'], '-log(0) is infinite, which is why models keep tiny probabilities above zero.'),
      tf('Dividing by n in the variance formula, instead of n - 1, slightly underestimates the true variance on small samples.', true, 'The deviations are measured from the sample mean, which is closer to the data than the true mean.')),

    L('Case study: tuning a fraud alert threshold',
      info('The scenario', 'A bank scores card payments. Each day there are **100 fraudulent** and **100,000 genuine** payments. The model raises an alert when its score passes a threshold, and analysts can review **300 alerts per day**.\n\nThreshold A catches 90% of fraud and falsely flags 1% of genuine payments. Threshold B catches 70% and falsely flags 0.2%. You choose.'),
      type('At threshold A, how many fraudulent payments are caught per day?', ['90'], '90% of 100.'),
      type('At threshold A, how many genuine payments are falsely flagged per day?', ['1000', '1,000'], '1% of 100,000.'),
      type('How many alerts does threshold A raise per day in total?', ['1090', '1,090'], '90 true alerts plus 1,000 false ones.'),
      mc('Roughly what share of threshold A alerts are real fraud?', ['About 8%', 'About 90%', 'About 1%', 'About 50%'], '90 / 1,090 is about 8.3%: the rare base rate dominates.'),
      type('How many alerts does threshold B raise per day in total?', ['270'], '70 caught (70% of 100) plus 200 false alarms (0.2% of 100,000).'),
      mc('Given the 300-alert review capacity, which threshold can the team actually work through?', ['B, because 270 alerts fit and A does not', 'A, because it catches more fraud', 'Neither', 'Both fit easily'], 'Alerts above capacity go unreviewed, so the catches of A are partly wasted.'),
      type('How many more fraudulent payments per day does A catch than B, if all its alerts were reviewed?', ['20'], '90 - 70 = 20.'),
      tf('Overall accuracy would look above 99% for both thresholds, so it hides this trade-off.', true, 'Almost all payments are genuine and almost all are correctly passed, so accuracy hardly changes.'),
      order('Choosing an alert threshold', ['Estimate the base rate of fraud', 'Compute alerts and precision at each threshold', 'Compare with review capacity and the cost of missed fraud', 'Pick a threshold and monitor it'], 'Decide from rates and costs, then keep checking as the data changes.')),

    L('Interview drill: probability and information',
      info('Answering well', 'Interview questions in this area are usually one of three kinds: **compute** (Bayes, expectation, a binomial), **explain** (what MLE is, why cross-entropy) or **apply** (choose a distribution or threshold).\n\nWork with natural frequencies (count 10,000 people) to avoid slips, and say the units: bits or nats, per hour or per minute.'),
      type('X is Binomial with n = 50 and p = 0.2. What is its variance?', ['8', '8.0'], 'n * p * (1 - p) = 50 * 0.2 * 0.8 = 8.'),
      type('P(spam) = 0.5, P(word | spam) = 0.4 and P(word | not spam) = 0.1. What is P(spam | word)? Give a decimal.', ['0.8', '4/5', '80%'], '0.2 / (0.2 + 0.05) = 0.8.'),
      type('A model gives probability 0.125 to the true class. What is its cross-entropy loss in bits?', ['3'], '-log2(1/8) = 3.'),
      mc('Why do we train classifiers with cross-entropy loss?', ['It is the negative log-likelihood of the labels under a categorical model', 'It is the only differentiable loss', 'It always equals accuracy', 'It makes outputs sum to 1'], 'Minimising it is maximum likelihood estimation.'),
      mc('What does a higher temperature do when sampling from a language model?', ['Flattens the distribution, so output is more varied', 'Makes output more deterministic', 'Adds more tokens', 'Changes the model weights'], 'Temperature divides the logits before the softmax.'),
      tf('KL divergence KL(p || q) always equals KL(q || p).', false, 'It is asymmetric.'),
      order('Structure of a strong Bayes answer', ['State Bayes’ rule', 'Name prior, likelihood and evidence for the problem', 'Compute with natural frequencies', 'Comment on the base rate and what it means'], 'The base-rate comment shows you understand the result, not just the formula.'),
      match('Match the idea to what it connects to', [['Mean squared error', 'Maximum likelihood with Gaussian noise'], ['Cross-entropy', 'Maximum likelihood with categorical labels'], ['Naive Bayes', 'Features independent given the class'], ['Temperature', 'Scales logits before the softmax']]))
  ]
};
